#pragma once
#include "ksStateFieldMapTask.h"
#include "ksStateStorageTask.h"
#include "ksStateParameterExpandTask.h"
#include "ksStatePanelModesTask.h"
#include <array>
#include <optional>
#include <type_traits>
namespace ks {
// Shared patch parameter support: packed-field mapping, current-part bindings,
// dirty publication and both complete expansion passes with signed semitone.
class NativeParameterSupportService final {
public:
 enum class Kind{Map,BindCurrent,BindPart,Dirty,Expand,Fields};enum class Component{Map,Storage,Expand,Semitone};
 struct Input{uint8_t parameter=0,value=0,part=0;uint32_t field=0,source=0,target=0;};struct Effect{bool read=false,write=false;};
 struct Summary{Kind kind=Kind::Map;Input input{};uint32_t descriptor=0,base=0,source=0,target=0;uint8_t part=0,mode=0,dirty=0,shifted=0,lastPacked=0,hardware=0,oldSemitone=0;bool bound=false,semitone=false;std::optional<StateFieldMapTask>map;std::optional<StateParameterExpandTask>expand;};
 explicit NativeParameterSupportService(Kind k):NativeParameterSupportService(k,Input{}){}NativeParameterSupportService(Kind k,Input i):kind_(k){summary_.kind=k;summary_.input=i;summary_.source=i.source;summary_.target=i.target;if(k==Kind::Map){map_.emplace(i.parameter,i.value,i.field);component_=Component::Map;}else if(k==Kind::Expand||k==Kind::Fields){expand_.emplace(k==Kind::Expand?StateParameterExpandTask::Entry::Refresh:StateParameterExpandTask::Entry::Fields);component_=Component::Expand;}else{storage_[0].emplace(k==Kind::BindCurrent?StateStorageTask::Kind::BindCurrent:k==Kind::BindPart?StateStorageTask::Kind::BindPart:StateStorageTask::Kind::Dirty,i.part);component_=Component::Storage;}components_=1u<<unsigned(component_);}
 Kind kind()const{return kind_;}bool complete()const{return complete_;}bool critical()const{return false;}Component component()const{return component_;}uint32_t components()const{return components_;}const Summary&summary()const{return summary_;}const Effect&effect()const{return effect_;}
 template<class T>const T*task()const{if(complete_)return nullptr;if constexpr(std::is_same_v<T,StateFieldMapTask>)return component_==Component::Map?&*map_:nullptr;else if constexpr(std::is_same_v<T,StateStorageTask>)return component_==Component::Storage?&*storage_[depth_-1]:nullptr;else if constexpr(std::is_same_v<T,StateParameterExpandTask>)return component_==Component::Expand?&*expand_:nullptr;else if constexpr(std::is_same_v<T,StatePanelModesTask>)return component_==Component::Semitone?&*semitone_:nullptr;else return nullptr;}
 unsigned nextClocks(int previous=-1)const{if(complete_)return 0;switch(component_){case Component::Map:return map_->nextClocks();case Component::Storage:return storage_[depth_-1]->nextClocks();case Component::Expand:return expand_->nextClocks(byteClock(summary_.target+expand_->targetOffset(),previous));case Component::Semitone:return semitone_->nextClocks(byteClock(semitone_->stage()==StatePanelModesTask::Stage::WriteOldSemitone?0x1678e:0x1678d,previous));}return 0;}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;effect_={};
  const auto wide=[&](uint32_t a){if(!span(a,4,false))throw std::logic_error("Unsupported parameter support pointer");uint32_t v=0;for(unsigned n=0;n<4;++n)v=(v<<8)|uint8_t(read((a+n)&0xffffff,cost-3*((3-n)/2)));return v;};const auto byte=[&](uint32_t a,unsigned back=0){if(!span(a,1,false))throw std::logic_error("Unsupported parameter support observation");return uint8_t(read(a&0xffffff,cost-back));};const auto put=[&](uint32_t a,uint8_t v){if(!span(a,1,true))throw std::logic_error("Unsupported parameter support publication");write(a&0xffffff,v,cost);};
  if(component_==Component::Map){using T=StateFieldMapTask;using S=T::Stage;const auto stage=map_->stage();map_->advanceBefore(cost,[&](T::Read r)->uint32_t{switch(r){case T::Read::Descriptor:summary_.descriptor=wide(72134+4*map_->descriptorNumber());if(!span(summary_.descriptor,256,false))throw std::logic_error("Unsupported packed descriptor");return summary_.descriptor;case T::Read::Base:summary_.base=wide(0x167bc);return summary_.base;case T::Read::Current:return byte(summary_.base+map_->field());default:{const auto v=byte(summary_.descriptor+map_->descriptorOffset(),r==T::Read::Field?0:2);if(r==T::Read::RightCount){summary_.shifted=summary_.input.value;for(unsigned n=0;n<v;++n)summary_.shifted>>=1;}return v;}}});if(map_->complete()){summary_.map=map_;complete_=true;effect_.read=true;}return cost;}
  if(component_==Component::Storage){using T=StateStorageTask;using S=T::Stage;auto&t=*storage_[depth_-1];const auto stage=t.stage();t.advanceBefore(cost,[&](T::Read r)->uint32_t{const auto v=byte(r==T::Read::Mode?0x167ba:r==T::Read::Part||r==T::Read::DirtyPart?0x17526:0x1679a);if(r==T::Read::Mode)summary_.mode=v;if(r==T::Read::Part||r==T::Read::DirtyPart)summary_.part=v;if(r==T::Read::Dirty)summary_.dirty=v;return v;},[&](T::Write r,uint32_t v){if(r==T::Write::Dirty){summary_.dirty=uint8_t(v);put(0x1679a,uint8_t(v));}else{const auto a=r==T::Write::CurrentBase?0x167bc:0x167c0;for(unsigned n=0;n<4;++n)write(a+n,uint8_t(v>>(24-8*n)),cost-3*((3-n)/2));}});
   effect_.write=stage==S::BindPartChild;effect_.read=stage==S::ReturnCurrent||stage==S::ReturnPart||stage==S::ReturnDirty;
   if(t.awaitingPart()){summary_.bound=true;storage_[depth_++].emplace(T::Kind::BindPart,t.part());}else if(t.complete()){if(t.kind()==T::Kind::BindPart){summary_.part=t.part();summary_.bound=true;}storage_[--depth_].reset();if(depth_)storage_[depth_-1]->resumePart();else complete_=true;}return cost;
  }
  if(component_==Component::Expand){using T=StateParameterExpandTask;using S=T::Stage;const auto stage=expand_->stage();expand_->advanceBefore(cost,[&](T::Read r)->uint32_t{if(r==T::Read::CurrentBase)return summary_.source=wide(0x167bc);if(r==T::Read::LiveBase)return summary_.target=wide(0x167c0);if(r==T::Read::Mode)return summary_.mode=byte(0x167ba);summary_.lastPacked=byte(summary_.source+expand_->sourceOffset());return summary_.lastPacked;},[&](unsigned at,uint8_t v){put(summary_.target+at,v);},byteClock(summary_.target+expand_->targetOffset(),previous));if(stage==S::CaptureCurrent)summary_.target=summary_.source;effect_.write=stage==S::DispatchFirst||stage==S::RetainRequest||stage==S::DispatchSigned;effect_.read=stage==S::RestoreRequest||stage==S::ReturnExpansion;if(expand_->awaitingSigned()){summary_.semitone=true;semitone_.emplace(StatePanelModesTask::Kind::Semitone,uint16_t(expand_->signedMode())<<8);select(Component::Semitone);}else if(expand_->complete()){summary_.expand=expand_;complete_=true;}return cost;
  }
  using T=StatePanelModesTask;using S=T::Stage;semitone_->advanceBefore(cost,[&](T::Read r,uint32_t)->uint32_t{if(r==T::Read::Type)return summary_.hardware=byte(0x158f2);return summary_.oldSemitone=byte(0x1678d);},[&](T::Write r,uint32_t,uint32_t v){put(r==T::Write::PreviousSemitone?0x1678e:0x1678d,uint8_t(v));},byteClock(semitone_->stage()==S::WriteOldSemitone?0x1678e:0x1678d,previous));if(semitone_->complete()){effect_.read=true;semitone_.reset();expand_->resumeSigned();select(Component::Expand);}return cost;
 }
 static bool span(uint32_t raw,unsigned n,bool writing){const auto a=raw&0xffffff;if(!n||a>0xffffffu-(n-1))return false;return (a>=0x15000&&a+n<=0x30000)||(!writing&&a>=0xb8e8&&a+n<=0x15000)||(a>=0xa15000&&a+n<=0xa30000)||(!writing&&a>=0x800000&&a+n<=0x900000);}
private:
 static unsigned byteClock(uint32_t a,int p){a&=0xffffff;return a<0x400000&&!(p&1)&&a==(uint32_t(p)|1u)?0:3;}void select(Component c){component_=c;components_|=1u<<unsigned(c);}
 Kind kind_;Component component_;uint32_t components_=0;bool complete_=false;Effect effect_{};Summary summary_{};std::optional<StateFieldMapTask>map_;std::array<std::optional<StateStorageTask>,2>storage_{};unsigned depth_=1;std::optional<StateParameterExpandTask>expand_;std::optional<StatePanelModesTask>semitone_;
};
}
